export const exampleHelpFundamentals = [
  ['2D coordinates and scalar grids', 'Direct paths use {nx,ny} coordinates in the normalized range [-1,1], with positive Y upward. contours(field,size,threshold) extracts stitched lines from a square row-major scalar grid: field[y*size+x]. Row zero maps to the bottom of the plot. These paths do not pass through a 3D camera or scene auto-fit.'],
  ['Coordinates and units', '3D coordinates are [X,Y,Z] in abstract world units, with Z up. They are not millimetres. G-code paper dimensions and margins determine physical size later. Cube size is 2 per axis; sphere radius is 1; cylinder radius is 0.8 and full height 2; torus major/tube radii are 0.68/0.32.'],
  ['Transform order', 'Builders return new shapes. Rendering applies scale, then X/Y/Z rotations, then translation. rotate() uses degrees; Math.sin/cos and Math.PI use radians. translate() is a world-space offset and is not scaled. Keep the returned builder or chain calls.'],
  ['Line density versus accuracy', 'Primitive detail is rounded/clamped to 4-18 and sets twice that many parameter intervals. Height-field/function lines controls drawn rows; samples controls the approximating mesh. More drawn lines mean more ink and pen motion, not automatically smoother geometry.'],
  ['Drawing and hiding are separate', 'Grid, edges, and silhouette choose strokes; the whole solid still hides other strokes. draw(\'none\') or occluder() hides the strokes only. occlude(false) disables the object as a blocker. Disconnected paths can be legitimate visibility breaks.'],
  ['Projection and paper size', 'The camera aims from position toward target with the supplied up vector. Visible output is automatically centred and fitted to about 92% of the normalized plot range. Moving a single object or changing uniform scale may not change its printed size. Use relative sizes, adjust G-code paper settings, or intentionally use fit:false.'],
  ['Safe workflow', 'These guides explain the bundled source, not your edited version. Viewing a guide never loads or executes code. Edit in the editor, then Generate (or Auto-generate). Cancel stops expensive jobs. Only run code you trust; workers keep the UI responsive but are not security sandboxes.'],
  ['Budgets and plotting', 'Jobs time out after 30 seconds. Limits include 12,000 scene objects, 100,000 source curves, 10 million visibility samples, and 20,000 output paths / 500,000 points. Start with low density, preview at your intended pen width, and check the G-code preview before plotting.'],
];

export function getExampleCameraHelp(example) {
  if (example.dimension === 2) return [];
  const vector = name => {
    const match = example.code.match(new RegExp(`${name}: (\\[[^\\]]+\\])`));
    if (!match) throw new Error(`Camera ${name} not found in example ${example.id}`);
    return match[1];
  };
  const position = vector('position');
  const target = vector('target');
  const up = vector('up');
  const fov = example.code.match(/fov: (\d+)/)?.[1];
  return [
    parameter(`position: ${position}`,
      'Camera eye [X,Y,Z] in world units. Positive Z raises the viewpoint; negative Y looks from that side of the scene. X changes the sideways viewpoint. These are positions, not rotation angles.',
      'Raise the Z component for a more top-down view. Keep eye different from target.'),
    parameter(`target: ${target}`,
      'Look-at point [X,Y,Z]. Z=-1 aims into a depression, Z=0.3 aims above ground, and [0,0,0] aims at the origin. This does not translate the artwork.',
      'Change target Z slightly to tilt the view while leaving the geometry untouched.'),
    parameter(`up: ${up}`,
      'The [0,0,1] vector declares positive Z to be vertical. Its zeros remove X/Y roll contributions; the one gives a nonzero direction. It must not be parallel to the viewing direction.',
      'Keep Z-up for these scenes. To look straight down Z, supply a different up direction such as [0,1,0].'),
    {
      code: fov ? `fov: ${fov}` : 'fov omitted (default 45 degrees)',
      meaning: 'Vertical perspective field of view. 45 degrees is a moderate perspective. All bundled examples auto-fit the visible result, so changing FOV alone is largely cancelled by fitting.',
      experiment: 'Change camera position for viewpoint/perspective changes. Use fit:false only if you want FOV to control framing directly; verify bounds before exporting.',
    },
  ];
}

export function getWalkthroughLine(example, section) {
  const index = example.code.indexOf(section.code);
  if (index < 0) throw new Error(`Help excerpt not found in ${example.id}: ${section.code}`);
  return example.code.slice(0, index).split('\n').length;
}
